"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66591"],{30243(e){e.exports=JSON.parse('{"id":"FIN-1285","slug":"debt-settlement","term":"Debt Settlement","also_known_as":[],"difficulty":"Intermediate","definition":"Debt settlement is an agreement between a borrower and a creditor in which the creditor accepts less than the full amount owed as final payment.","explanation":["Borrowers in serious financial difficulty may negotiate with creditors to settle debts for a reduced amount, often paid as a lump sum. Creditors may agree if they believe the borrower cannot repay in full and that a partial payment is better than nothing.","For example, someone who owes 10,000 on a credit card and cannot keep up with payments might negotiate a settlement of 6,000, with the remaining 4,000 written off.","Debt settlement can reduce what a borrower pays, but it has significant downsides. Settled accounts damage credit records, often for several years. Some debt settlement companies charge high fees and advise clients to stop paying creditors while they save up, which can lead to late fees, collection activity and legal action. In the United States, forgiven debt above a small amount may be treated as taxable income.","Alternatives include debt management plans arranged through non-profit credit counselling, consolidation loans and, in serious cases, formal insolvency procedures. Free, independent debt advice can help borrowers choose the best option."],"note":"","total":1500,"prev":{"slug":"debt-service-coverage-ratio","term":"Debt Service Coverage Ratio (DSCR)"},"next":{"slug":"debt-snowball","term":"Debt Snowball"}}')}}]);